module TestMapping
  # The text of specs/docs/test_mapping.md: the generated line, the summary table, the totals,
  # one section per AC, and the tests with no known AC.
  class Document
    GENERATED = "Generated by `bin/rails test_mapping:write` from the test names and the plans. " \
      "Do not edit this file by hand: run `docker compose run --rm backend bin/rails test_mapping:write` " \
      "to write it again, and `docker compose run --rm backend bin/rails test_mapping:check` to check it."
    NINE_CASES = "The nine cases that requirements.md section 7 requires are mapped by hand in the README's " \
      "[Test coverage](../../README.md#test-coverage)."
    # The ACs whose result is a document (specs/README.md): their plans' Docs checks are their
    # acceptance.
    DOCUMENT_ACS = %w[AC-07 AC-26 AC-28 AC-29 AC-30].freeze

    def initialize(repository)
      @repository = repository
    end

    def text
      [ GENERATED, summary, totals, NINE_CASES, *ac_sections, unknown_section ].join("\n\n") + "\n"
    end

    # The tests with no known AC: no AC ID at the start of the name, or an ID that requirements.md
    # section 10 does not have. They are listed under no AC.
    def unknown_tests
      tests.reject { |test| known?(test) }
    end

    # The backend tests that are not skipped, each counted once.
    def backend_total
      backend_count(tests)
    end

    def frontend_total
      frontend_count(tests)
    end

    private

    def acceptance_criteria
      @repository.acceptance_criteria
    end

    def tests
      @repository.tests
    end

    def known?(test)
      test.ids.any? && (test.ids - acceptance_criteria.map(&:id)).empty?
    end

    def tests_of(ac)
      tests.select { |test| known?(test) && test.ids.include?(ac.id) }
    end

    def backend_count(tests)
      tests.count { |test| test.counted? && test.backend? }
    end

    def frontend_count(tests)
      tests.count { |test| test.counted? && !test.backend? }
    end

    def automated?(ac)
      tests_of(ac).any?(&:counted?)
    end

    def covered?(ac)
      automated?(ac) || manual_parts(ac).any?
    end

    # The plan's Test plan, when it has at least one item, and for an AC whose result is a document,
    # the checks of the plan's Docs, when it has at least one. Each links to its section.
    def manual_parts(ac)
      plan = @repository.plans[ac.id] or return []

      parts = []
      if plan.test_plan_items.positive?
        items = "#{plan.test_plan_items} #{"item".pluralize(plan.test_plan_items)}"
        parts << "[Test plan: #{items}, #{plan.test_plan_passed} passed](../features/#{plan.folder}/plan.md#test-plan)"
      end
      if DOCUMENT_ACS.include?(ac.id) && plan.docs_checks.positive?
        parts << "[Docs checks: #{plan.docs_checks}, #{plan.docs_ticked} ticked](../features/#{plan.folder}/plan.md#docs)"
      end
      parts
    end

    def manual_validation(ac)
      return manual_parts(ac).join("; ") if manual_parts(ac).any?

      automated?(ac) ? "None" : "Not covered"
    end

    def summary
      rows = acceptance_criteria.map do |ac|
        "| [#{ac.id}](##{ac.id.downcase}) | #{ac.text} | #{backend_count(tests_of(ac))} | " \
          "#{frontend_count(tests_of(ac))} | #{manual_validation(ac)} |"
      end
      [
        "| AC | Acceptance criterion | Backend tests | Frontend tests | Manual validation |",
        "|---|---|---|---|---|",
        *rows
      ].join("\n")
    end

    # Every test that is not skipped counts once, and each AC once.
    def totals
      automated = acceptance_criteria.count { |ac| automated?(ac) }
      manual_alone = acceptance_criteria.count { |ac| !automated?(ac) && covered?(ac) }
      not_covered = acceptance_criteria.count { |ac| !covered?(ac) }
      "Totals: #{backend_count(tests)} backend tests and #{frontend_count(tests)} frontend tests; " \
        "a test listed under two ACs counts once. " \
        "Of the #{acceptance_criteria.size} ACs, #{automated} have automated tests, " \
        "#{manual_alone} rely on manual validation alone, and #{not_covered} are not covered."
    end

    def ac_sections
      acceptance_criteria.map do |ac|
        [ "## #{ac.id}", ac.text, coverage(ac), test_list(tests_of(ac)) ].compact.join("\n\n")
      end
    end

    def coverage(ac)
      return "Not covered." unless covered?(ac)

      "Backend tests: #{backend_count(tests_of(ac))}. Frontend tests: #{frontend_count(tests_of(ac))}. " \
        "Manual validation: #{manual_validation(ac)}."
    end

    # One item per test file, with one sub-item per test in the file's order. None without tests.
    def test_list(tests)
      return if tests.empty?

      tests.group_by(&:file).map do |file, file_tests|
        [ "- [#{file}](../../#{file})", *file_tests.map { |test| "  - #{test.name}#{" (skipped)" if test.skipped}" } ]
      end.join("\n")
    end

    # A test whose name is not plain text shows its first line as written.
    def unknown_section
      items = unknown_tests.map do |test|
        "- [#{test.file}](../../#{test.file}): #{test.name || TestMapping.inline_code(test.first_line)}"
      end
      "## Tests with no known AC\n\n#{items.empty? ? "None." : items.join("\n")}"
    end
  end
end
